/**
 * Gear metrology — the B-rep tooth counter, pinned against a known-truth gear.
 *
 * The fixture pair is `tests/fixtures/cad-parts/gear-m3-z38.{step,prediction.json,truth.json}`:
 * a true involute spur gear generated by `scripts/gen-test-gear.py` with m=3,
 * z=38, b=30, bore Ø40 — so OD = m(z+2) = 120.00 mm EXACTLY, and every number
 * the metrology recovers has an analytic right answer.
 *
 * The prediction is a RECORDING (CI has no cadquery), same pattern as the
 * golden-parts harness. When cadquery IS present (dev boxes, the CAD Docker
 * image in CI), the recording is re-measured live and must match — a stale
 * recording after a metrology change fails here rather than in production.
 */
import { describe, it, expect } from 'vitest';
import { readFileSync, existsSync } from 'fs';
import { join } from 'path';
import { execFileSync } from 'child_process';

const DIR = join(__dirname, 'fixtures', 'cad-parts');
const STEP = join(DIR, 'gear-m3-z38.step');
const ENGINE = join(__dirname, '..', 'server', 'utils', 'cad-geometry-engine.py');

interface GearMetrics {
  likelyGear: boolean; teeth: number; tipDiameterMm: number; faceWidthMm: number;
  boreDiameterMm: number; derivedNormalModuleMm: number; helixAngleDeg: number | null;
  internal: boolean; moduleBasis: string; teethBasis: string;
}

function assertTruth(gear: GearMetrics, volumeCm3: number): void {
  expect(gear.likelyGear).toBe(true);
  expect(gear.teeth).toBe(38);                          // counted, not guessed
  expect(gear.derivedNormalModuleMm).toBeCloseTo(3.0, 2);
  expect(gear.tipDiameterMm).toBeCloseTo(120.0, 1);
  expect(gear.faceWidthMm).toBeCloseTo(30.0, 1);
  expect(gear.boreDiameterMm).toBeCloseTo(40.0, 1);
  expect(gear.internal).toBe(false);
  // Helix is a drawing question — deriving it from the B-rep is the hallucination
  // this layer exists to prevent. It must stay null, whatever the flanks look like.
  expect(gear.helixAngleDeg).toBeNull();
  expect(gear.moduleBasis).toContain('z 38 + 2');
  expect(gear.teethBasis).toContain('38 tip-circle patch');
  expect(volumeCm3).toBeCloseTo(265.96, 0);
}

describe('gear metrology vs the known-truth involute gear', () => {
  const rec = JSON.parse(readFileSync(join(DIR, 'gear-m3-z38.prediction.json'), 'utf-8'));

  it('recorded prediction recovers z=38, m=3.0, OD=120, b=30, bore=40', () => {
    assertTruth(rec.gear as GearMetrics, rec.volume.cm3 as number);
  });

  it('live re-measure matches the recording (skipped without cadquery)', () => {
    let hasCadquery = false;
    try {
      execFileSync('python3', ['-c', 'import cadquery'], { stdio: 'ignore', timeout: 30_000 });
      hasCadquery = true;
    } catch { /* CI without OCP — the recording carries the check */ }
    if (!hasCadquery || !existsSync(STEP)) {
      console.warn('[gear-metrology] cadquery unavailable — live re-measure skipped, recording stands');
      return;
    }
    const out = JSON.parse(execFileSync('python3', [ENGINE, STEP],
      { maxBuffer: 64 * 1024 * 1024, timeout: 180_000 }).toString());
    assertTruth(out.gear as GearMetrics, out.volume.cm3 as number);
    expect(out.gear.teeth).toBe(rec.gear.teeth);
    expect(out.gear.tipDiameterMm).toBeCloseTo(rec.gear.tipDiameterMm, 3);
  });
});
